    with c_p4:
        if st.button("🪤 Adversarial Negative Trap", use_container_width=True):
            st.session_state.active_query = "Which Indian quick-commerce company raised a $1.2B funding round led by SoftBank in August 2024?"

    current_val = st.session_state.get(
