    .badge-supported { background: #065f46; color: #34d399; border: 1px solid #10b981; }
    .badge-contradicted { background: #7f1d1d; color: #f87171; border: 1px solid #ef4444; }
    .badge-unsupported { background: #78350f; color: #fbbf24; border: 1px solid #f59e0b; }
    .badge-unverifiable { background: #1e293b; color: #cbd5e1; border: 1px solid #64748b; }
    .badge-nocitation { background: #4c1d95; color: #c084fc; border: 1px solid #a855f7; }

    /* Pipeline Step Tracker */
    .step-track {
        display: flex;
