        border-radius: 10px;
        padding: 12px 16px;
    }
    .step-node {
        display: flex;
        align-items: center;
        font-size: 0.85rem;
        font-weight: 600;
        color: #cbd5e1;
    }
    .step-node.active {
        color: #38bdf8;
    }
    .step-num {
        width: 24px;
        height: 24px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.15);
