# 2. Resilient Direct DuckDuckGo Lite search (fast, robust, bypasses Bing timeouts)
try:
    from bs4 import BeautifulSoup
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    }
    async with httpx.AsyncClient(timeout=6.0, follow_redirects=True) as client:
        resp = await client.post("https://lite.duckduckgo.com/lite/", data={"q": query}, headers=headers)
        if resp.status_code == 200 and "result-link" in resp.text:
            soup = BeautifulSoup(resp.text, "html.parser")
            items = []
            for a in soup.find_all("a", class_="result-link"):
                href = a.get("href", "").strip()
                title = a.get_text(strip=True)
                if href.startswith("http") and "duckduckgo.com" not in href:
                    # snippet if available in following td
                    snippet = ""
                    parent_tr = a.find_parent("tr")
                    if parent_tr:
                        next_tr = parent_tr.find_next_sibling("tr")
                        if next_tr:
                            snippet_td = next_tr.find("td", class_="result-snippet")
                            if snippet_td:
                                snippet = snippet_td.get_text(strip=True)
                    items.append(
                        SearchResultItem(
                            title=title,
                            url=href,
                            snippet=snippet or title,
                        )
                    )
                    if len(items) >= max_results:
                        break
            if items:
                duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000
                return SearchResult(
                    query=query,
                    engine="duckduckgo_lite",
                    items=items,
                    duration_ms=duration_ms,
                )
except Exception:
    pass  # Fall back to ddgs package

# 3. Fallback to DDGS library
try:
    loop = asyncio.get_event_loop()

    def _sync_ddg():
        with DDGS(timeout=5) as ddgs:
            return list(ddgs.text(query, max_results=max_results))

    raw_results = await loop.run_in_executor(None, _sync_ddg)
    duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000

    items = [
        SearchResultItem(
            title=r.get("title", ""),
            url=r.get("href", ""),
            snippet=r.get("body", ""),
        )
        for r in raw_results
    ]
    return SearchResult(
        query=query,
        engine="duckduckgo",
        items=items,
        duration_ms=duration_ms,
