import asyncio
import re
import urllib.parse
from typing import Optional
from pydantic import BaseModel
import httpx
from bs4 import BeautifulSoup
from duckduckgo_search import DDGS

from app.core.config import settings

class SearchResultItem(BaseModel):
    title: str
    url: str
    snippet: str

class SearchResult(BaseModel):
    query: str
    engine: str
    items: list[SearchResultItem]
    duration_ms: float = 0.0
    error: Optional[str] = None

class UpgradedSearchEngine:
    def __init__(self, tavily_api_key: Optional[str] = None):
        self.tavily_api_key = tavily_api_key or settings.tavily_api_key
        self.headers = {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/124.0.0.0 Safari/537.36"
            ),
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.9",
        }

    def _clean_query(self, query: str) -> str:
        q = re.sub(r"^(what is|what are|who is|who was|how many|when was|tell me about|find|can you tell me)\s+", "", query, flags=re.I)
        q = re.sub(r"[\?\"\'\(\)\[\]\{\}]", " ", q)
        q = re.sub(r"\s+", " ", q).strip()
        return q or query

    def _clean_url(self, raw_url: str) -> str:
        u = raw_url.strip()
        if "duckduckgo.com/l/?uddg=" in u:
            match = re.search(r"uddg=([^&]+)", u)
            if match:
                u = urllib.parse.unquote(match.group(1))
        # Remove tracking params
        parsed = urllib.parse.urlparse(u)
        q_params = urllib.parse.parse_qsl(parsed.query)
        clean_params = [(k, v) for k, v in q_params if not k.startswith("utm_") and k not in ("ref", "fbclid")]
        new_query = urllib.parse.urlencode(clean_params)
        return urllib.parse.urlunparse(parsed._replace(query=new_query))

    async def _search_ddg_lite(self, query: str, max_results: int) -> list[SearchResultItem]:
        async with httpx.AsyncClient(headers=self.headers, timeout=6.0, follow_redirects=True) as client:
            resp = await client.post("https://lite.duckduckgo.com/lite/", data={"q": query})
            if resp.status_code == 200 and "result-link" in resp.text:
                soup = BeautifulSoup(resp.text, "html.parser")
                items = []
                for a in soup.find_all("a", class_="result-link"):
                    href = a.get("href", "").strip()
                    title = a.get_text(strip=True)
                    if href.startswith("http") and "duckduckgo.com" not in href:
                        snippet = ""
                        parent_tr = a.find_parent("tr")
                        if parent_tr:
                            next_tr = parent_tr.find_next_sibling("tr")
                            if next_tr:
                                snippet_td = next_tr.find("td", class_="result-snippet")
                                if snippet_td:
                                    snippet = snippet_td.get_text(strip=True)
                        items.append(
                            SearchResultItem(
                                title=title,
                                url=self._clean_url(href),
                                snippet=snippet or title,
                            )
                        )
                        if len(items) >= max_results:
                            break
                return items
        return []

    async def _search_wikipedia(self, query: str, max_results: int) -> list[SearchResultItem]:
        clean_q = self._clean_query(query)
        try:
            async with httpx.AsyncClient(timeout=4.0) as client:
                resp = await client.get(
                    "https://en.wikipedia.org/w/api.php",
                    params={"action": "opensearch", "search": clean_q, "limit": max_results, "format": "json"},
                    headers={"User-Agent": "facTrack-Agent/1.0"},
                )
                if resp.status_code == 200:
                    data = resp.json()
                    titles = data[1] if len(data) > 1 else []
                    snippets = data[2] if len(data) > 2 else []
                    urls = data[3] if len(data) > 3 else []
                    items = []
                    for t, s, u in zip(titles, snippets, urls):
                        if u and u.startswith("http"):
                            items.append(SearchResultItem(title=t, url=u, snippet=s or t))
                    return items
        except Exception:
            pass
        return []

    async def search(self, query: str, max_results: int = settings.max_search_results) -> SearchResult:
        start_time = asyncio.get_event_loop().time()

        # 1. Tavily if available
        if self.tavily_api_key:
            try:
                async with httpx.AsyncClient(timeout=8.0) as client:
                    resp = await client.post(
                        "https://api.tavily.com/search",
                        json={"api_key": self.tavily_api_key, "query": query, "search_depth": "basic", "max_results": max_results},
                    )
                    if resp.status_code == 200:
                        data = resp.json()
                        items = [
                            SearchResultItem(title=r.get("title", ""), url=self._clean_url(r.get("url", "")), snippet=r.get("content", ""))
                            for r in data.get("results", [])
                        ]
                        if items:
                            duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000
                            return SearchResult(query=query, engine="tavily", items=items, duration_ms=duration_ms)
            except Exception:
                pass

        # 2. DuckDuckGo Lite (Direct Fast POST)
        try:
            items = await self._search_ddg_lite(query, max_results)
            if items:
                duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000
                return SearchResult(query=query, engine="duckduckgo_lite", items=items, duration_ms=duration_ms)
        except Exception:
            pass

        # 3. Query Relaxation on DuckDuckGo Lite if initial query had 0 results
        clean_q = self._clean_query(query)
        if clean_q != query:
            try:
                items = await self._search_ddg_lite(clean_q, max_results)
                if items:
                    duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000
                    return SearchResult(query=query, engine="duckduckgo_lite_relaxed", items=items, duration_ms=duration_ms)
            except Exception:
                pass

        # 4. Wikipedia OpenSearch API fallback
        try:
            wiki_items = await self._search_wikipedia(query, max_results)
            if wiki_items:
                duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000
                return SearchResult(query=query, engine="wikipedia", items=wiki_items, duration_ms=duration_ms)
        except Exception:
            pass

        # 5. DDGS fallback with safe timeout
        try:
            loop = asyncio.get_event_loop()
            def _sync():
                with DDGS(timeout=4) as ddgs:
                    return list(ddgs.text(clean_q, max_results=max_results))
            raw = await loop.run_in_executor(None, _sync)
            items = [
                SearchResultItem(title=r.get("title", ""), url=self._clean_url(r.get("href", "")), snippet=r.get("body", ""))
                for r in raw if r.get("href")
            ]
            if items:
                duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000
                return SearchResult(query=query, engine="duckduckgo_ddgs", items=items, duration_ms=duration_ms)
        except Exception:
            pass

        duration_ms = (asyncio.get_event_loop().time() - start_time) * 1000
        return SearchResult(query=query, engine="none", items=[], duration_ms=duration_ms, error="No search results found.")

async def main():
    se = UpgradedSearchEngine()
    test_queries = [
        "who is the founder of NVIDIA",
        "silver rate in chennai today",
        "Swiggy IPO valuation and date",
        "Python GIL free-threaded python 3.13",
    ]
    for q in test_queries:
        res = await se.search(q, max_results=3)
        print(f"\nQUERY: {q}")
        print(f"ENGINE: {res.engine} | DURATION: {res.duration_ms:.1f}ms | ITEMS: {len(res.items)}")
        for it in res.items:
            print(f"  - {it.title} -> {it.url}")

if __name__ == "__main__":
    asyncio.run(main())

